:root {
  --cream: #f5ead8;
  --brown: #7a4e2d;
  --red: #c0392b;
  --gold: #d4a017;
  --divider: #c9b89a;
  --text-dark: #3b2a1a;
  --stamp-bg: #eaf3e8;
  --stamp-border: #4a7c59;
}

.postcard {
  background-color: var(--cream);
  border: 2px solid var(--divider);
  border-radius: 6px;
  width: 460px;
  padding: 16px;
  margin: 20px auto;
}

.postcard-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 2px dashed var(--divider);
  padding-bottom: 8px;
  margin-bottom: 14px;
}

.postcard-label {
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 4px;
  color: var(--brown);
  text-transform: uppercase;
}

.postcard-date {
  font-size: 11px;
  font-weight: 600;
  color: var(--red);
  letter-spacing: 2px;
}

.postcard-body {
  display: flex;
  gap: 16px;
  align-items: flex-start;
}

.postcard-message {
  flex: 1;
  border-right: 2px dashed var(--divider);
  padding-right: 16px;
}

.message-text {
  font-size: 13px;
  line-height: 1.7;
  color: var(--text-dark);
  margin: 0 0 10px 0;
}

.postcard-sig {
  font-size: 12px;
  font-weight: 700;
  color: var(--brown);
  display: block;
  text-align: right;
}

.postcard-right {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 14px;
  width: 110px;
}

.stamp-box {
  width: 60px;
  height: 68px;
  border: 3px solid var(--stamp-border);
  border-radius: 3px;
  background-color: var(--stamp-bg);
  display: flex;
  align-items: center;
  justify-content: center;
  outline: 3px dotted var(--stamp-border);
  outline-offset: -6px;
}

.stamp-inner {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
}

.stamp-icon {
  font-size: 20px;
  line-height: 1;
}

.stamp-value {
  font-size: 10px;
  font-weight: 700;
  color: var(--stamp-border);
  letter-spacing: 1px;
}

.address-lines {
  display: flex;
  flex-direction: column;
  gap: 8px;
  width: 100%;
}

.address-line {
  display: block;
  height: 2px;
  background-color: var(--divider);
  border-radius: 2px;
  width: 100%;
}

.address-line.short {
  width: 60%;
  align-self: flex-end;
}
